import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";var i=JSON.parse(`{"title":"利用規約","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/terms.md","filePath":"ja/guide/terms.md","lastUpdated":1793173149000}`),a={name:`ja/guide/terms.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="利用規約" tabindex="-1">利用規約 <a class="header-anchor" href="#利用規約" aria-label="Permalink to “利用規約”">​</a></h1><p>本規約は、Sudoku アプリケーションの利用について定めるものです。Sudoku をダウンロード、インストール、または使用することにより、お客様は本規約に同意したものとみなされます。同意されない場合は、本アプリケーションを使用しないでください。</p><h2 id="ライセンスと利用" tabindex="-1">ライセンスと利用 <a class="header-anchor" href="#ライセンスと利用" aria-label="Permalink to “ライセンスと利用”">​</a></h2><p>Sudoku は、各リリースに含まれるライセンス条項に基づいて提供されます。お客様には、ライセンス条項に従い、お客様のデバイス上で本アプリケーションを使用するための、限定的、非独占的、かつ譲渡不能なライセンスが付与されます。</p><h2 id="オフラインファーストの設計と任意のクラウド機能" tabindex="-1">オフラインファーストの設計と任意のクラウド機能 <a class="header-anchor" href="#オフラインファーストの設計と任意のクラウド機能" aria-label="Permalink to “オフラインファーストの設計と任意のクラウド機能”">​</a></h2><p>Sudoku はオフラインファーストのアプリケーションです。設定、ゲームの状態、統計などのすべてのゲームデータは、既定でお使いのデバイス内にローカル保存されます。</p><p>任意のクラウド機能には以下が含まれます：</p><ul><li><strong>iCloud 同期</strong>（CloudKit 経由）：お客様個人の iCloud アカウントを使用して、Apple デバイス間でデータを同期します。</li><li><strong>Game Center</strong>：リーダーボードと実績を提供します。</li><li><strong>「More Apps」</strong>：姉妹アプリの一覧を取得する任意の機能です。個人データは送信されません。</li></ul><p>お客様が明示的にオプトインした場合に Apple の iCloud および Game Center サービスによって管理される情報を除き、当社が個人データを収集することはありません。</p><h2 id="ユーザーの責任" tabindex="-1">ユーザーの責任 <a class="header-anchor" href="#ユーザーの責任" aria-label="Permalink to “ユーザーの責任”">​</a></h2><ul><li>Sudoku を適用法令および関連する規則に従って合法的に使用すること。</li><li>ライセンスに違反して本アプリを逆コンパイル、リバースエンジニアリング、または改変しようとしないこと。</li><li>本アプリを違法な目的で使用しないこと。</li></ul><h2 id="プライバシー" tabindex="-1">プライバシー <a class="header-anchor" href="#プライバシー" aria-label="Permalink to “プライバシー”">​</a></h2><p>データの取り扱いについては、プライバシーポリシーをご確認ください。要約すると、当社はデータを収集しません。任意のクラウド機能は、お客様の明示的な同意のもとで Apple の iCloud および Game Center サービスのみを使用します。</p><h2 id="保証の否認" tabindex="-1">保証の否認 <a class="header-anchor" href="#保証の否認" aria-label="Permalink to “保証の否認”">​</a></h2><p>Sudoku は「現状有姿」で提供され、いかなる種類の保証も行いません。法律で認められる最大限の範囲において、メンテナーは、明示的、黙示的、法定その他を問わず、商品性および特定目的への適合性を含むすべての保証を否認します。</p><h2 id="責任の制限" tabindex="-1">責任の制限 <a class="header-anchor" href="#責任の制限" aria-label="Permalink to “責任の制限”">​</a></h2><p>法律で認められる最大限の範囲において、メンテナーは、本アプリケーションの使用に起因する間接的、偶発的、特別、結果的または懲罰的な損害について、一切の責任を負いません。</p><h2 id="終了" tabindex="-1">終了 <a class="header-anchor" href="#終了" aria-label="Permalink to “終了”">​</a></h2><p>お客様が本規約に従わなかった場合、お客様に付与された権利は自動的に終了します。</p><h2 id="変更" tabindex="-1">変更 <a class="header-anchor" href="#変更" aria-label="Permalink to “変更”">​</a></h2><p>当社は本規約を随時更新することがあります。変更後も引き続き使用された場合、改訂後の規約に同意したものとみなされます。</p><h2 id="お問い合わせ" tabindex="-1">お問い合わせ <a class="header-anchor" href="#お問い合わせ" aria-label="Permalink to “お問い合わせ”">​</a></h2><p>本規約に関するご質問は、プロジェクトリポジトリ（<code>https://github.com/sudoku-pro/sudoku-site/issues</code>）で issue を作成してください。</p><p><em>最終更新：2026-07-29</em></p>`,24)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};